from author_library import *
cards=[]
cards.append(compact('qiu_lun','丘伦','丘伦是走遍世界的自由摄影记者，习惯用镜头记录危险、奇观与人的行为。他曾进入游击队活动区、秘密集会和高山，也借特殊设备拍摄深海和微小物体，不能把摄影设备的承受条件算成他肉身的潜水或高速能力。三十二岁时，他同联合国翻译员海文约会，本来准备说出感情，却在湖边看到一个外貌酷似刚夺权的齐洛将军、神情又异常空白的人。他职业性的观察和追索超过了维持浪漫气氛的愿望，举起相机追拍，循车辆去向查到勒曼医院。之后反复探查，最终死亡，遗骸多年后才被发现。杜良叙述他翻墙跌落撞到水泥凸起而死、医院掩埋遗体；卫斯理起初怀疑谋杀，终局没有提供独立目击去重建每一瞬间，因此卡片采用已亡事实并注明死因来源。后来出现的同貌者是从其细胞培育的后备体，没有继承记者的思想。若演绎恢复丘伦，应恢复本人最后生前状态，保留好奇、敏锐与对现场的执着，不让他以空白后备体名义无损复活。','《后备》本人已亡；杜良说明翻墙事故，后备体没有本人意识；部署恢复生前记者人身','主角','记录异常事实，不让重要镜头和线索从眼前消失','观察细节很快，遇到新奇现场先考虑怎样留下可靠图像','追索目标时可能把安全和亲密关系暂时放在后面','照片是证据却仍需解释；熟悉危险不等于能应付所有隐秘机构',[ab('摄影与现场观察','使用随身相机及专业设备记录人物特征和危险场面','设备不同于身体能力；突然震惊时也曾忘记拍摄'),ab('旅行与调查经验','凭脚力、访查和线索追踪接近秘密','没有卫斯理级武术证据，翻越高墙发生致命风险')],[ev('055',23,41,'职业与经历'),ev('055',69,145,'识人追拍与关系选择'),ev('055',2416,2430,'死亡说明'),ev('055',3160,3163,'后备不是本人复生')],profile='investigator',extra={'adaptations':[{'change':'恢复最后生前记者人身，不使用空白后备体作为人格复活证明。','reason':'本人已死且复制未带记忆。','power_impact':'不增加复活或组织资源。'}]}))
cards.append(compact('hai_wen','海文','海文在联合国机构担任翻译，外表出众，熟悉社交生活，也习惯被人重视。她同丘伦相识后多次约会，却在一次本该浪漫的湖边相聚中被对方追逐异常人物的行为冷落；她当时生气，丘伦也没有详细解释，关系留下未说清的部分。多年后丘伦遗骸出现，她带着照片和线索找到卫斯理，并不是仅作为等待答案的旧情人。她在当地继续调查医院历年病人，整理名单，甚至在看见同貌的后备体后误以为丘伦仍活着，希望医生尽力救助。她的行动提供了关键推动，也让“同一张脸是否就是同一个人”的问题有了具体感情重量。最终卫斯理因保密承诺没有告诉她全部复制技术，编了另一个解释，她没有继续追究；原文并未确定她完全相信还是选择停止。终局卡保留专业语言能力、调查韧性和会受伤的自尊，不把第一次约会生气概括成全部人格。她有权想知道旧识的真实命运，也可能在听不到完整答案时留下怀疑，不能自动演成掌握勒曼所有秘密的知情者。','《后备》接受或至少不再追问卫斯理给出的解释，未被告知完整后备技术','主角','弄清丘伦的遭遇，也维护自己不被轻忽的尊严','语言清楚，善于在社会关系中获取信息，对敷衍敏感','见到貌似旧识的病人时感情先动，仍会主动寻找帮助','熟悉一个人的容貌不能证明眼前身体拥有相同意识',[ab('翻译和资料调查','以职业语言能力和实际走访取得医院名单、联系相关人员','不默认通晓所有语言；未获完整科学真相')],[ev('055',134,151,'约会反应与职业'),ev('055',490,563,'提供遗骸及照片线索'),ev('055',1740,1748,'调查病人名单'),ev('055',3182,3190,'未被告知真实结局')],profile='expert'))
cards.append(compact('sha_ling','沙灵','沙灵是卫斯理的老朋友，英国出身的保安专家，曾在情报机构任高级职务，到六十六岁仍身体结实、头脑敏捷。他为阿潘特王子负责护卫工作，对一个冒名者造成的轻微伤口没有简单放过，而是持续追查类似事件，把在不同国家发生的小伤和特殊访客联系起来。他同卫斯理讨论可能的毒药勒索，又愿意在假说不成立后继续调整，不把老资格当成证据。王子后来因病进入勒曼医院，沙灵知道消息公开可能引起争位和政局震荡，因而对调查者的好奇既理解又有职业上的顾虑。他能看出围绕生命和巨额财富的事情可疑，却也只能在职责、保密和朋友信任之间选择。终局卫斯理向他保证事情不必再追查，他基于多年交情接受，没有获得全部后备技术内幕。卡片保留他的防护意识、情报网络和成熟审慎，不把他服务的王室力量全算作本人装备，也不把信任朋友写成愚钝。他会先问消息泄露给谁、对雇主和公众有何后果，再决定怎样核实。','《后备》继续承担护卫与保密职责，相信卫斯理保证而停止追问','主角','确保受保护者安全，辨明潜在威胁又避免情报造成次生危机','持续整理零散事件，与可信朋友交换推理','涉及雇主病情和继承风险时谨慎设限，要求对方理解后果','推测必须接受事实修正，私人信任也有明确的关系来源',[ab('保安与情报调查','追查身份、伤口和跨地区异常，熟悉保护重要人物的程序','终局所知有缺口，不能自动解密医院或指挥全部政府机关')],[ev('055',261,267,'身份与年龄状态'),ev('055',338,405,'跨案调查与假说'),ev('055',1787,1799,'保密原因'),ev('055',3192,3195,'信任朋友的结局')],profile='investigator'))
cards.append(compact('ge_deng','哥登','哥登是勒曼医院早期向卫斯理揭示秘密的科学家之一，大胡子外形与自信的语气使他在解释研究时格外突出。他同杜良、罗克等人组成的团队通过整容和隐匿身份离开原有社会位置，把工作看作走在时代前面的科学探索，喜欢以哥白尼的精神为自己辩护。其研究培育与目标人物相同的后备身体，在原身器官无法医治时提供替换，由此改变富豪和权贵对死亡的理解。他强调并未制造客户的疾病，而是提前等待需要出现；在费用问题上又把科研同社会资源的交易看得相当坦然。卫斯理质疑后备体挣扎是否说明它们想要自由，他坚持这些是实验室产品，并提出带对方亲自察看生活状态。卡片不替这场争论下绝对结论：他的科学成就和对生命主体的狭窄定义同时存在。后期医院的全部新技术不能无证叠加到他个人手上，终局采用最后确认的研究人员身份，个人下落没有独立续写。他需要设备、团队和可获取样本，离开医院不意味着随手就能复制任何生命。','《后备》留在勒曼研究团队，后续个人去向未明确；按已证实的技术与职责部署','阶段性对立者','推进能够延续生命的研究，并维护团队工作获得正当性的信念','善于长篇解释，强调先驱者会遭误解，相信实物展示能说服别人','受到伦理质疑时倾向重新定义对象，必要时公开研究现场','技术可行性不能自动解决人格与同意问题；本人仍会遇到证据和道德挑战',[ab('后备身体研究','参与细胞培育、器官替换和团队研究，能解释其流程','需要完整设施、团队和样本；不是即时复制战斗技能'),ab('科学论证与组织协作','解释研究的目的、费用和边界以取得外部合作','对后备体意识的论断仍是其立场，不强制叙事认定为终极事实')],[ev('055',2442,2480,'形貌、科学家身份与整容'),ev('055',3068,3094,'后备机制及非致病说明'),ev('055',3124,3149,'伦理争论与展示')],profile='expert'))
cards.append(compact('luo_ke','罗克','罗克是勒曼医院研究与联络体系中的人物，初见卫斯理时冒充著名医生的私人代表，径直进入陶启泉病房，用生命即将结束的现实压过普通礼节。他不耐烦、带嘲讽，要求与客户单独谈话，甚至用“快死的人还有什么可害”的逻辑说服卫斯理离开。他的强硬并非单纯空口欺骗：医院确有后备身体和替换器官的技术，陶启泉接受安排后恢复健康，但假身份和选择性信息仍是他取得接触的手段。到秘密公开时，他又参与解释费用模式和后备体所谓无意识的状态，把挣扎说成生物自然反应，把交易说成自愿。他与哥登、杜良的立场有重叠，却在现场更锐利、更喜欢用对方逻辑的漏洞反击。终局卡保留这种会谈、组织与研究背景，不把整个医院后来的外星能力都归给他个人。他能安排有条件的帮助，却不能在脱离机构、没有样本和设备时凭一句承诺治好任何人；面对新的知情同意问题，他可能先维护程序，也必须承受别人拒绝交易的后果。','《后备》继续参与勒曼医院研究与客户联络，个人后续能力未另获确认','阶段性对立者','把需要生命延续的客户与医院资源连接，并保护研究体系的持续','言辞锋利而直接，用实际需求突破礼貌障碍','被质疑可信度时以结果和反问压迫对方，回避无关人士旁听','需求急迫不能替代真实身份与知情选择，其自愿论应接受检验',[ab('医疗联络与谈判','寻找需要后备医疗的目标，以秘密方式达成合作','技术由医院实施；假冒代表的手法有失去信任的代价'),ab('后备研究知识','参与团队并解释复制体培养及基础意识问题','不把说明能力当作随身复制设备或任意精神控制')],[ev('055',864,928,'假代表身份与病房谈判'),ev('055',3103,3136,'费用论证和后备体争议'),ev('055',3164,3183,'团队职责与保密')],profile='expert'))
cards.append(compact('a_pante','阿潘特王子','阿潘特原是拥有石油收益背景的王室人物，身边有沙灵等专业人员保护，轻微的手背伤口也会接受详细检查。他并不知道那类接近行为与医院预先取得样本有关，直到胃癌使普通医疗无法挽救自己，才进入勒曼医院特殊体系。对他来说，后备医疗不仅是一项奇迹，也意味着必须支付自己当时不能自由支配的巨大资源。卫斯理调查时，沙灵担心病情消息外泄会引发继承争夺，王子的私人生命早已同政治秩序纠缠。治疗之后，他返回本国，数月内发动成功政变，成为能够自由支配石油收益的元首，政变造成多人死亡。原文将这与支付医院条件相连，同时承认政变责任不能简单全推给医院。终局卡以获得政权、接受过医疗的人类统治者为基础；后备体不是免死护符，今后治疗仍需机构条件。他的求生愿望可以理解，牺牲别人以支付生命代价的选择也必须保留，不能只用“被医院逼迫”抹掉其个人决定。','《后备》治疗后发动政变并成为元首，能够支配本国石油收益','反派','保住自己的生命和支配资源的地位','依赖专业护卫与秘密医疗安排，在重大利益问题上保持保密','面对无法自行承担的治疗代价时选择夺取更高权力','求生与政治选择的责任不可分离；医院服务不保证永久不死',[ab('王室与政治动员','通过既有王族地位发动政变、掌控资源','所需人手和军力是具体政治关系，不作个人随身火力'),ab('后备医疗渠道','曾接受勒曼医院对严重疾病的处理','非自愈能力，未来是否获得服务仍需样本、设施和合作')],[ev('055',256,267,'伤口与护卫背景'),ev('055',1787,1799,'病情的政治影响'),ev('055',3024,3028,'胃癌治疗背景'),ev('055',3210,3214,'政变和死亡代价')],profile='ordinary'))
cards.append(compact('qi_luo','齐洛将军','齐洛将军在《后备》开端已经通过缜密阴谋夺取一个亚洲国家政权，公开演说时接受群众欢呼，私下继续清除反对势力。他对自己的形象十分敏感，护卫因丘伦拍摄过近将记者殴打拘押，随后他把人带来审看照片，尤其关心左脸两颗并列的痣是否被不利地突出。得到摄影师“表现坚强性格”的解释后，他满意地放人，仍提醒不要作不利报道。这段具体交锋呈现出一个需要赞美、又能把暴力称作误会的掌权者。湖边后来出现的同貌苍白人并不是他秘密流落街头，而是勒曼医院培养的后备体；那人的空白目光、逃出训练区域和被带回的动作，不能反过来算成齐洛本人的失常或行动。小说没有交代将军后来的政权结局，卡片保持最后确认的人类统治者状态，不替他安排病愈或被推翻。其危险来自权力机构对个人的压迫和控制叙述的习惯，背后的复制技术是机构给予的潜在服务，不是个人会使用的能力。','《后备》最后确认仍为夺权后的国家元首；湖边同貌者是独立后备体，非本人','反派','巩固政权并控制公众看到的个人形象','注意礼仪和照片细节，愿意在得到恭维后表现宽容','认为形象或安全受威胁时由护卫先压制，再决定是否解释为误会','其自我形象与真实暴力可以同时存在，不能按其说法抹除受害者经历',[ab('政治威势与形象管理','依靠军政地位和护卫控制接触、审查照片、巩固支持','军队不是个人身体能力，终局未证实独立超常本领')],[ev('055',69,105,'政变身份、拘押及照片交锋'),ev('055',111,125,'本人政治处境与后备体区分'),ev('055',3059,3063,'明确湖边者为后备')],profile='ordinary'))
save(cards)
cover('055',[('卫斯理','wei_sili','主角','调查后备秘密'),('白素','bai_su','主角','协作调查'),('丘伦','qiu_lun','主角','摄影见证与追查起点'),('海文','hai_wen','主角','持续调查和旧情推动'),('沙灵','sha_ling','主角','跨案调查和王室保安'),('陶启泉','tao_qiquan','主角','危病与治疗选择'),('杜良','du_liang','阶段性对立者','医院研究者'),('哥登','ge_deng','阶段性对立者','解释研究与伦理立场'),('罗克','luo_ke','阶段性对立者','接触客户及研究'),('勒曼医院','leman_hospital','阶段性对立者','机构共同技术与决策'),('阿潘特','a_pante','反派','为支配收益发动政变'),('齐洛','qi_luo','反派','独裁与记者拘押')],[('巴纳德医生','被冒名的医疗专家背景，未把真实人物资料扩写成虚构主要角色'),('丘伦、齐洛等后备体','具有身体和自然动作，但未建立可区分自主人格；保留伦理疑问，不重复本人的卡'),('杨副董事长与其他医护、护卫','一次性执行者，没有独立主要对抗目标')],['丘伦死亡本身确认；具体事故过程来自杜良叙述。医院隐瞒身份与伦理问题不能自动证明每项谋杀猜测。'])
